    function _cleanDefaultValue(value) {
      if (value === undefined || value === null || value === "None") return "";
      let text = String(value);
      if ((text.startsWith("'") && text.endsWith("'")) || (text.startsWith('"') && text.endsWith('"'))) text = text.slice(1, -1);
      return text;
    }

